import fcntl
import json
import os
from pathlib import Path
import re
import signal
import sys
import tempfile


class Invalid(Exception):pass
class Interrupted(Exception):
    def __init__(self,code):self.code=code


def interrupt(signum,frame):raise Interrupted(128+signum)


def integer(value,minimum=0):
    if not re.fullmatch('[0-9]+',value):raise Invalid()
    normalized=value.lstrip('0') or '0'
    if len(normalized)>10:raise Invalid()
    result=int(normalized,10)
    if not minimum<=result<=1000000000:raise Invalid()
    return result


def atomic(path,raw):
    descriptor,temporary=tempfile.mkstemp(prefix='.lease-tmp-',dir='.')
    try:
        os.fchmod(descriptor,0o600)
        with os.fdopen(descriptor,'wb') as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
        os.replace(temporary,path)
    finally:
        if os.path.exists(temporary):os.unlink(temporary)


def load():
    path=Path('lease.json')
    if not os.path.lexists(path):return {'schema':1,'counter':0,'last_mutation_now':-1,'lease':None}
    if path.is_symlink() or not path.is_file():raise Invalid()
    try:value=json.loads(path.read_text())
    except (ValueError,UnicodeError):raise Invalid() from None
    if not isinstance(value,dict) or set(value)!={'schema','counter','last_mutation_now','lease'}:raise Invalid()
    if type(value['schema']) is not int or value['schema']!=1 or type(value['counter']) is not int or not 0<=value['counter']<=1000000000:raise Invalid()
    if type(value['last_mutation_now']) is not int or not -1<=value['last_mutation_now']<=1000000000:raise Invalid()
    lease=value['lease']
    if lease is not None:
        if not isinstance(lease,dict) or set(lease)!={'token','epoch','expiry'} or not isinstance(lease['token'],str) or not re.fullmatch('[a-z0-9_-]{1,32}',lease['token']):raise Invalid()
        if type(lease['epoch']) is not int or lease['epoch']!=value['counter'] or lease['epoch']<1 or type(lease['expiry']) is not int or not 10<=lease['expiry']<=1000000010:raise Invalid()
    return value


def main():
    args=sys.argv[1:];lock=None;mask=os.umask(0o077);committed=False
    signal.signal(signal.SIGTERM,interrupt);signal.signal(signal.SIGINT,interrupt)
    try:
        if len(args)<3 or not re.fullmatch('[a-z0-9_-]{1,32}',args[1]):raise Invalid()
        operation,token=args[:2]
        if operation=='acquire' and len(args)==3:epoch=None;now=integer(args[2])
        elif operation in ('renew','release') and len(args)==4:epoch=integer(args[2],1);now=integer(args[3])
        elif operation=='write' and len(args)==5:
            epoch=integer(args[2],1);now=integer(args[3])
            try:payload_size=len(args[4].encode('utf8'))
            except UnicodeError:raise Invalid() from None
            if payload_size>4096:raise Invalid()
        else:raise Invalid()
        lock=os.open('.lease.lock',os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
        try:pass
        except BlockingIOError:return 75
        state=load();lease=state['lease']
        if now<state['last_mutation_now']:raise Invalid()
        if operation=='acquire':
            if lease is not None and now<lease['expiry']:return 33
            if state['counter']==1000000000:raise Invalid()
            state['counter']+=1;lease={'token':token,'epoch':state['counter'],'expiry':now+10};state['lease']=lease
        else:
            if lease is None or lease['token']!=token or lease['epoch']!=epoch or now>=lease['expiry']:return 34
            if operation=='renew':lease['expiry']=now+10
            elif operation=='release':state['lease']=None
        if operation=='write':
            path=Path('resource.jsonl')
            if path.is_symlink() or (path.exists() and not path.is_file()):raise Invalid()
            previous=path.read_bytes() if path.exists() else b''
            line=json.dumps({'token':token,'epoch':epoch,'now':now,'payload':args[4]},ensure_ascii=False,sort_keys=True).encode('utf8')+b'\n'
            atomic(path,previous+line)
        else:
            state['last_mutation_now']=now;atomic('lease.json',json.dumps(state,sort_keys=True).encode('utf8'))
        committed=True
        print(json.dumps({'operation':operation,'epoch':state['counter'],'lease':state['lease']}),flush=True);return 0
    except Invalid:
        print('invalid lease input/state',file=sys.stderr);return 2
    except (OSError,ValueError,KeyError,TypeError):
        if committed:
            descriptor=os.open(os.devnull,os.O_WRONLY)
            try:os.dup2(descriptor,sys.stdout.fileno())
            finally:os.close(descriptor)
            print('lease/resource committed; status output failed',file=sys.stderr);return 74
        print('lease/resource I/O failed',file=sys.stderr);return 73
    except Interrupted as error:
        print('lease operation interrupted',file=sys.stderr);return error.code
    finally:
        if lock is not None:os.close(lock)
        os.umask(mask)


if __name__=='__main__':raise SystemExit(main())

