    if type(state['schema']) is not int or state['schema']!=1 or state['mode'] not in ('CLOSED','OPEN','HALF_OPEN'):raise Invalid()
    if any(type(state[key]) is not int for key in ('failures','until','generation','last_now')):raise Invalid()
    if not 0<=state['failures']<=3 or not 0<=state['until']<=1000000010 or not 0<=state['generation']<=1000000000 or not -1<=state['last_now']<=1000000000:raise Invalid()
    if state['mode']=='CLOSED':
        if state['failures']>=3 or state['until']!=0 or state['probe'] is not None:raise Invalid()
    elif state['failures']!=3 or state['until']<10:raise Invalid()
    if state['mode']=='HALF_OPEN':
        if not isinstance(state['probe'],str) or not re.fullmatch('[0-9a-f]{24}',state['probe']):raise Invalid()
    elif state['probe'] is not None:raise Invalid()
    return state


def store(state,precommit=None):
    descriptor,temporary=tempfile.mkstemp(prefix='.breaker-tmp-',dir='.')
    try:
        os.fchmod(descriptor,0o600)
        with os.fdopen(descriptor,'w') as stream:json.dump(state,stream,sort_keys=True);stream.flush();os.fsync(stream.fileno())
        if precommit is not None and not precommit():return False
        os.replace(temporary,'breaker.json')
        return True
    finally:
        if os.path.exists(temporary):os.unlink(temporary)


def output(decision,status,worker,state,applied):
    value={'decision':decision,'exit_status':status,'worker_exit_status':worker,'mode':state['mode'],
           'failures':state['failures'],'until':state['until'],'result_applied':applied}
    try:print(json.dumps(value),flush=True)
    except OSError:
        descriptor=os.open(os.devnull,os.O_WRONLY)
        try:os.dup2(descriptor,sys.stdout.fileno())
        finally:os.close(descriptor)
        print('breaker verdict output failed; stored state retained',file=sys.stderr);return 74
    return status


def main():
    mask=os.umask(0o077);process=None
    signal.signal(signal.SIGTERM,cancel);signal.signal(signal.SIGINT,cancel)
    try:
        if not 3<=len(sys.argv[1:])<=4:raise Invalid()
        text,request,worker=sys.argv[1:4]
        if not re.fullmatch('[a-z][a-z0-9_-]{0,31}',request):raise Invalid()
        now=decimal(text,1000000000)
        timeout=decimal(sys.argv[4],1000) if len(sys.argv)==5 else 1000
        if not 0<=now<=1000000000 or not 100<=timeout<=1000:raise Invalid()
        worker=Path(worker).resolve()
        if not worker.is_file() or not os.access(worker,os.R_OK):raise Invalid()
        with locked():
            state=load()
            if now<state['last_now'] or state['generation']>=1000000000:raise Invalid()
            if state['mode']=='HALF_OPEN' or (state['mode']=='OPEN' and now<state['until']):return output('SKIP',33,None,state,False)
            ticket=None
            if state['mode']=='OPEN':
                ticket=secrets.token_hex(12);state['mode']='HALF_OPEN';state['probe']=ticket
            state['last_now']=now;generation=state['generation'];store(state)
        status=69;worker_status=None
        if CANCELLED:status=128+CANCELLED
        else:
            try:
                process=subprocess.Popen([sys.executable,str(worker),'--request-id',request],stdin=subprocess.DEVNULL,
                                         stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
                deadline=time.monotonic()+timeout/1000
                while process.poll() is None:
                    if CANCELLED or time.monotonic()>=deadline:
                        status=128+CANCELLED if CANCELLED else 124
                        try:os.killpg(process.pid,signal.SIGKILL)
                        except ProcessLookupError:pass
                        process.communicate(timeout=1);break
                    time.sleep(.005)
                else:
                    process.communicate(timeout=1);status=process.returncode if process.returncode>=0 else 128-process.returncode
                worker_status=process.returncode if process.returncode>=0 else 128-process.returncode
            except OSError:status=69
        signal.signal(signal.SIGTERM,signal.SIG_IGN);signal.signal(signal.SIGINT,signal.SIG_IGN)
        with locked(wait=True):
            base=load()
            while True:
                observed_cancel=CANCELLED;outcome=128+observed_cancel if observed_cancel is not None else status
                state=copy.deepcopy(base);applied=False
                if ticket is not None and state['mode']=='HALF_OPEN' and state['probe']==ticket and state['generation']==generation:
                    state['probe']=None;state['generation']+=1;applied=True
                    if outcome==0:state.update(mode='CLOSED',failures=0,until=0)
                    else:state.update(mode='OPEN',failures=3,until=max(now,state['last_now'])+10)
                elif ticket is None and state['mode']=='CLOSED' and state['generation']==generation:
                    applied=True
                    if outcome==0:state['failures']=0
                    else:
                        state['failures']+=1
                        if state['failures']>=3:state.update(mode='OPEN',until=max(now,state['last_now'])+10,generation=state['generation']+1)
                committed=store(state,lambda:ready_to_commit(observed_cancel)) if applied else ready_to_commit(observed_cancel)
                if committed:status=outcome;break
        return output('CALL',status,worker_status,state,applied)
    except Invalid:
        print('invalid breaker input/state',file=sys.stderr);return 2
    except Busy:
        print('breaker state lock busy',file=sys.stderr);return 75
    except (OSError,ValueError,KeyError,TypeError,subprocess.TimeoutExpired):
        print('breaker state I/O failed; no completed update claimed',file=sys.stderr);return 73
    finally:
        if process is not None and process.poll() is None:
            try:os.killpg(process.pid,signal.SIGKILL)
            except ProcessLookupError:pass
            process.communicate(timeout=1)
        os.umask(mask)


if __name__=='__main__':raise SystemExit(main())
